class Solution {
  private static final String[] BELOW_20 = {"", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine", "Ten",
      "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen", "Seventeen", "Eighteen", "Nineteen"};
  private static final String[] TENS = {"", "", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"};
  private static final String[] SCALES = {"", "Thousand", "Million", "Billion"};

  public String numberToWords(int num) {
    if (num == 0) return "Zero";
    StringBuilder sb = new StringBuilder();
    for (int i = 3; i >= 0; i--) {
      int chunk = (int) (num / Math.pow(1000, i)) % 1000;
      if (chunk == 0) continue;
      sb.append(' ').append(threeDigits(chunk));
      if (i > 0) sb.append(' ').append(SCALES[i]);
    }
    return sb.toString().trim();
  }

  private String threeDigits(int n) {
    StringBuilder sb = new StringBuilder();
    if (n >= 100) sb.append(BELOW_20[n / 100]).append(" Hundred ");
    n %= 100;
    if (n >= 20) sb.append(TENS[n / 10]).append(' ').append(BELOW_20[n % 10]);
    else sb.append(BELOW_20[n]);
    return sb.toString().trim();
  }
}
